package com.bananalab.lite;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class Stage82ChainConflictCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);BananaTransformer m;try(InputStream in=Files.newInputStream(root.resolve("assets/lector3/lector32.bin"))){m=BananaTransformer.container(in);}
  // Library: larger cap, room report, trimming only old web pages
  check(NotebookDisk.MAX_DOCUMENTS==4096&&PageCrawl.MAX_PAGES<=NotebookDisk.MAX_DOCUMENTS,"library cap");CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();final NotebookDisk disk=NotebookDisk.of(c);
  String filler=" Este texto agrega contenido suficiente para que el documento tenga varias oraciones útiles y distintas entre sí.";
  disk.put("Faro Brumel",new StringReader("El faro Brumel es una torre ficticia de la costa de Quirema. El faro Brumel fue construido por Tomás Rivel en 1890. Su luz se ve desde cuarenta kilómetros."+filler),"https://example.com/faro","web");Thread.sleep(5);
  disk.put("Tomás Rivel",new StringReader("Tomás Rivel fue un ingeniero ficticio de Quirema. Tomás Rivel nació en 1851 en Altamisa. Estudió en la escuela de puentes de Belorado. Murió en 1923 en Tindal."+filler),"https://example.com/rivel","web");Thread.sleep(5);
  disk.put("Nota mía",new StringReader("La trufelina es una resina ficticia que mide 12 centímetros de espesor."+filler),"user","user");Thread.sleep(5);
  disk.put("Enciclopedia",new StringReader("La trufelina es una resina ficticia que mide 40 centímetros de espesor. La brumelia es una planta ficticia de hojas azules."+filler),"https://example.com/enciclopedia","web");Thread.sleep(5);
  disk.put("Otra enciclopedia",new StringReader("La brumelia es una planta ficticia de hojas azules y tallo corto."+filler),"https://example.com/otra","web");
  String room=disk.room();check(room.startsWith("Biblioteca: 5 de 4096 documentos (4 de la web, 1 tuyos)"),"room: "+room);
  check(KnowledgeNotebook.parse("hacé lugar en la biblioteca").kind.equals("library_room")&&KnowledgeNotebook.parse("borrá las 50 páginas más viejas").text.equals("50")&&KnowledgeNotebook.parse("borra las 3 lecturas web mas antiguas").kind.equals("library_trim")&&KnowledgeNotebook.parse("buscá contradicciones").kind.equals("conflicts")&&KnowledgeNotebook.parse("contradicciones entre mis fuentes")!=null,"library and conflict phrases");
  // Contradictions between sources
  JSONArray sample=NotebookDisk.rows(disk.index.sample(600),200,4);List<SourceConflicts.Pair> pairs=SourceConflicts.find(sample);check(pairs.size()==1&&ChatLanguage.normalize(pairs.get(0).term).contains("trufelina")&&pairs.get(0).why.equals("figures"),"only the term with different figures is flagged: "+pairs.size());
  String report=SourceConflicts.describe(pairs,sample.length());check(report.contains("12 centímetros")&&report.contains("40 centímetros")&&report.contains("aporte del usuario")&&report.contains("https://example.com/enciclopedia")&&report.contains("No sé cuál es correcta"),"both versions with their sources: "+report);
  check(SourceConflicts.differ("un metal de 3 kilos","un metal de 3 kilos y brillo")==null&&"figures".equals(SourceConflicts.differ("mide 3 metros","mide 9 metros"))&&"wording".equals(SourceConflicts.differ("un pez pequeño de aguas frías del norte","una herramienta metálica para cortar madera dura"))&&SourceConflicts.differ("una planta azul","una planta azul de tallo corto")==null,"difference rules");
  check(SourceConflicts.report(c).contains("trufelina")&&SourceConflicts.disputed(c).contains("trufelina")&&SourceConflicts.describe(new ArrayList<SourceConflicts.Pair>(),3).contains("No encontré"),"scan stores the disputed terms");
  String text="La trufelina es una resina ficticia que mide 40 centímetros de espesor. La brumelia es una planta ficticia de hojas azules. Los artesanos de Quirema la usan para sellar vasijas.";LectorTraining.disputed=new HashSet<String>();int free=LectorTraining.batch(m,null,text,null,false).definitions;LectorTraining.disputed=SourceConflicts.disputed(c);LectorTraining.Batch guarded=LectorTraining.batch(m,null,text,null,false);for(LectorTraining.Probe p:guarded.probes)check(!p.study.equals("que es la trufelina"),"a disputed definition is not studied");check(free==2&&guarded.definitions==1,"the other definition is still studied: "+free+" "+guarded.definitions);LectorTraining.disputed=new HashSet<String>();
  // Two-step questions
  String[] parts=LectorChain.split("¿Cuándo nació quien construyó el faro Brumel?");check(parts!=null&&parts[0].equals("quien construyo faro brumel")&&parts[1].equals("cuando nacio %s")&&LectorChain.split("cuando nacio tomas rivel")==null&&LectorChain.split("que es un faro")==null,"question shape: "+Arrays.toString(parts));
  check("Tomás Rivel".equals(LectorChain.name("El faro Brumel fue construido por Tomás Rivel en 1890.","faro brumel"))&&"Lucía de la Vega".equals(LectorChain.name("La obra fue escrita por la poeta Lucía de la Vega.","la obra"))&&LectorChain.name("El faro fue construido en 1890.","faro")==null&&LectorChain.name("El Faro Brumel fue construido hace mucho.","faro brumel")==null,"name extraction");
  LectorChain.Retriever library=new LectorChain.Retriever(){public JSONArray rows(String q)throws Exception{return disk.selected(q);}};
  LectorChain.Chain chain=LectorChain.follow(m,library,"¿Cuándo nació quien construyó el faro Brumel?");check(chain!=null&&chain.first.sentence.contains("construido por Tomás Rivel")&&chain.name.equals("Tomás Rivel")&&chain.second.sentence.equals("Tomás Rivel nació en 1851 en Altamisa.")&&chain.first.row.getString("source").endsWith("/faro")&&chain.second.row.getString("source").endsWith("/rivel"),"two readings joined by the name: "+(chain==null?null:chain.first.sentence+" | "+chain.name+" | "+chain.second.sentence));
  LectorChain.Chain died=LectorChain.follow(m,library,"donde murio quien construyo el faro brumel");check(died!=null&&died.second.sentence.contains("Tindal"),"another second step: "+(died==null?null:died.second.sentence));
  check(LectorChain.follow(m,library,"cuando nacio quien pinto el faro brumel")==null||true,"an unsupported first step may or may not be found; it never throws");check(LectorChain.follow(m,library,"cuando nacio quien fundo la ciudad de zarandel")==null,"nothing is chained when the first step is not in the library");
  check(LectorChain.reply(c,"¿Cuándo nació quien construyó el faro Brumel?")==null,"without the model asset the chain steps aside");
  // Trim
  List<NotebookDisk.Doc> gone=disk.forgetOldestWeb(2);check(gone.size()==2&&gone.get(0).title.equals("Faro Brumel")&&gone.get(1).title.equals("Tomás Rivel")&&disk.index.count()==3,"the two oldest web pages go first");check(disk.selected("faro brumel").length()==0&&disk.selected("trufelina").length()==2,"their text is no longer retrieved; the rest stays");
  gone=disk.forgetOldestWeb(50);check(gone.size()==2&&disk.index.count()==1&&disk.index.list(10).get(0).origin.equals("user"),"the user's own note is never removed");check(disk.forgetOldestWeb(5).isEmpty()&&disk.room().contains("(0 de la web, 1 tuyos)"),"nothing left to trim");
  disk.put("Nueva",new StringReader("La nuevalina es una página ficticia agregada después de hacer lugar."+filler),"https://example.com/nueva","web");check(disk.index.count()==2,"the library accepts documents after trimming");
  System.out.println("PASS Stage82 larger library with trimming of old web pages only, contradictions between sources kept out of study, and two-step questions joined by a name");
 }
}
